window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-065a44fd5d4bd49a"]={"versions": [{"id": "FIG-065a44fd5d4bd49a", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Konfigurationsmetamodell-Ausschnitt für das Modul <code>Can</code> (CAN-Treiber) gemäß AUTOSAR-ECUC-Metamodell. Dargestellt ist das Schema der Konfigurationscontainer und -parameter für das Feature Pretended Networking / ICOM (Inter-Client Operational Model / Intelligent Configuration Optimization Model bzw. Inter-ECU Communication Optimization).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Konfigurationscontainer und Parameter-Entitäten:</p>\n<ul class=\"fig-list\"><li>Container <code>CanIcom</code> (Typ: <code>EcucParamConfContainerDef</code>, Multiplizität: 0..1): Wurzelcontainer für ICOM-Konfigurationen im CAN-Treiber.\n<ul class=\"fig-list\"><li>Aggregationsbeziehung (<code>+subContainer</code>, Komposition mit ausgefüllter Raute) zu <code>CanIcomConfig</code>.\n</li></ul>\n</li><li>Container <code>CanIcomConfig</code> (Typ: <code>EcucParamConfContainerDef</code>, Multiplizität: 1..*): Definiert eine konkrete ICOM-Konfigurationsmenge. Enthält:\n<ul class=\"fig-list\"><li><code>CanIcomConfigId</code> (Typ: <code>EcucIntegerParamDef</code>, Rolle: <code>+parameter</code>): Ganzzahlige ID der Konfiguration mit Wertebereich <code>min = 1</code>, <code>max = 255</code>.\n</li><li><code>CanIcomWakeOnBusOff</code> (Typ: <code>EcucBooleanParamDef</code>, Rolle: <code>+parameter</code>): Boolescher Parameter mit Vorgabewert <code>defaultValue = true</code>.\n</li><li>Container <code>CanIcomWakeupCauses</code> (Typ: <code>EcucParamConfContainerDef</code>, Rolle: <code>+subContainer</code>): Aggregierter Untercontainer zur Definition von Wakeup-Ursachen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Deklarationsmodell zur Konfigurationszeit; kein dynamischer Sequenz- oder Laufzeitablauf abgebildet. Die Struktur definiert die Instanziierungs- und Schachtelungsregeln im BSW-Konfigurator bei der Generierung der CAN-Treiber-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Struktur für die Generierung und Validierung des CAN-Treibers:</p>\n<ul class=\"fig-list\"><li>Ein CAN-Treiber-BSW-Modul kann Pretended Networking optional unterstützen (<code>lowerMultiplicity = 0</code>). Falls <code>CanIcom</code> konfiguriert wird, muss mindestens eine ICOM-Konfiguration (<code>CanIcomConfig</code>, 1..*) vorliegen.\n</li><li>Jede ICOM-Konfiguration besitzt eine eindeutige Identifikationsnummer (<code>CanIcomConfigId</code>) im Wertebereich 1 bis 255.\n</li><li>Bei Aktivierung ist <code>CanIcomWakeOnBusOff</code> standardmäßig aktiviert (<code>true</code>).\n</li><li>Wakeup-Bedingungen werden hierarchisch im Untercontainer <code>CanIcomWakeupCauses</code> spezifiziert.\n</li></ul>"}, {"id": "FIG-f54c5830bdf38597", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Konfigurationsmetamodell-Ausschnitt für das Modul <code>Can</code> (CAN-Treiber) gemäß AUTOSAR-ECUC-Metamodell. Dargestellt ist das Schema der Konfigurationscontainer und -parameter für das Feature Pretended Networking / ICOM (Inter-Client Operational Model / Intelligent Configuration Optimization Model bzw. Inter-ECU Communication Optimization).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Konfigurationscontainer und Parameter-Entitäten:</p>\n<ul class=\"fig-list\"><li>Container <code>CanIcom</code> (Typ: <code>EcucParamConfContainerDef</code>, Multiplizität: 0..1): Wurzelcontainer für ICOM-Konfigurationen im CAN-Treiber.\n<ul class=\"fig-list\"><li>Aggregationsbeziehung (<code>+subContainer</code>, Komposition mit ausgefüllter Raute) zu <code>CanIcomConfig</code>.\n</li></ul>\n</li><li>Container <code>CanIcomConfig</code> (Typ: <code>EcucParamConfContainerDef</code>, Multiplizität: 1..*): Definiert eine konkrete ICOM-Konfigurationsmenge. Enthält:\n<ul class=\"fig-list\"><li><code>CanIcomConfigId</code> (Typ: <code>EcucIntegerParamDef</code>, Rolle: <code>+parameter</code>): Ganzzahlige ID der Konfiguration mit Wertebereich <code>min = 1</code>, <code>max = 255</code>.\n</li><li><code>CanIcomWakeOnBusOff</code> (Typ: <code>EcucBooleanParamDef</code>, Rolle: <code>+parameter</code>): Boolescher Parameter mit Vorgabewert <code>defaultValue = true</code>.\n</li><li>Container <code>CanIcomWakeupCauses</code> (Typ: <code>EcucParamConfContainerDef</code>, Rolle: <code>+subContainer</code>): Aggregierter Untercontainer zur Definition von Wakeup-Ursachen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Deklarationsmodell zur Konfigurationszeit; kein dynamischer Sequenz- oder Laufzeitablauf abgebildet. Die Struktur definiert die Instanziierungs- und Schachtelungsregeln im BSW-Konfigurator bei der Generierung der CAN-Treiber-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Struktur für die Generierung und Validierung des CAN-Treibers:</p>\n<ul class=\"fig-list\"><li>Ein CAN-Treiber-BSW-Modul kann Pretended Networking optional unterstützen (<code>lowerMultiplicity = 0</code>). Falls <code>CanIcom</code> konfiguriert wird, muss mindestens eine ICOM-Konfiguration (<code>CanIcomConfig</code>, 1..*) vorliegen.\n</li><li>Jede ICOM-Konfiguration besitzt eine eindeutige Identifikationsnummer (<code>CanIcomConfigId</code>) im Wertebereich 1 bis 255.\n</li><li>Bei Aktivierung ist <code>CanIcomWakeOnBusOff</code> standardmäßig aktiviert (<code>true</code>).\n</li><li>Wakeup-Bedingungen werden hierarchisch im Untercontainer <code>CanIcomWakeupCauses</code> spezifiziert.\n</li></ul>"}], "trans": [{"from": "FIG-065a44fd5d4bd49a", "to": "FIG-f54c5830bdf38597", "fr": "R4.2.2", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Vereinheitlichung der Typ- und Rollenbezeichner: Leerzeichen vor dem Doppelpunkt in den Containernamen und Parameternamen entfernt (<code>CanIcom :</code> -&gt; <code>CanIcom:</code>, <code>CanIcomConfig :</code> -&gt; <code>CanIcomConfig:</code>, <code>CanIcomConfigId :</code> -&gt; <code>CanIcomConfigId:</code>, <code>CanIcomWakeOnBusOff :</code> -&gt; <code>CanIcomWakeOnBusOff:</code>, <code>CanIcomWakeupCauses :</code> -&gt; <code>CanIcomWakeupCauses:</code>).\n</li><li>Layout- und Neu-Rendering-Anpassung der Box- und Verbindungslinien.\n</li></ul>"}]};
